mapper.select:
SELECT w.id AS waitingId, w.patient_id AS patientId, w.sch_id AS scheduleRecordId, w.apply_time AS applyTime, w.status
FROM waiting_queue w
WHERE w.id = #{waitingId}

SELECT w.id AS waitingId, w.patient_id AS patientId, w.sch_id AS scheduleRecordId, w.apply_time AS applyTime, w.status
FROM waiting_queue w
JOIN doc_schedule_record dsr ON w.sch_id = dsr.id
WHERE w.patient_id = #{patientId}

    AND CAST(dsr.schedule_date AS VARCHAR) = #{date}

ORDER BY dsr.schedule_date DESC, w.apply_time DESC
